import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { useClaims } from '../claims/useClaims';
import { usePeople } from '../people/usePeople';
import { useRates } from '../rates/useRates';
import { useFloor, useLate } from '../settings/useSettings';
import { DATE, periodDue, periodsKey, usePeriods, type Period } from './usePeriods';

/**
 * The sheet's periods, each with its due-total — the figures of everyone's counted (OPEN or
 * SETTLED) claims dated in it, not OPEN ones dated within their person's hold unless stated, n/a ones skipped — and one form to add a period: a name unique on
 * the sheet and a from and to date, inclusive, overlapping no other period. A period can be closed:
 * its due-total is then the one it had when it was closed, whatever rates do later. A steward can
 * reopen a closed period, making its due-total live again.
 */
function PeriodsPanel({ user, sheet }: { user: string; sheet: string }) {
  const queryClient = useQueryClient();
  const { data: periods = [] } = usePeriods(sheet);
  const { data: all = [] } = useClaims(sheet);
  const { data: people = [] } = usePeople(sheet);
  const { data: rates = [] } = useRates(sheet);
  const floor = useFloor(sheet);
  const late = useLate(sheet);
  const [name, setName] = useState('');
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const [invalid, setInvalid] = useState<string | null>(null);
  // The period whose last close or reopen was refused: its row shows the error.
  const [refused, setRefused] = useState<string | null>(null);

  const submitOnce = useSubmitOnce();
  const save = useMutation({
    mutationFn: (p: { name: string; from: string; to: string }) =>
      postJson<Period>(`/api/sheets/${encodeURIComponent(sheet)}/periods`, { ...p, user }),
    onSuccess: async () => {
      setName('');
      setFrom('');
      setTo('');
      await queryClient.invalidateQueries({ queryKey: periodsKey(sheet) });
    },
  });

  const close = useMutation({
    mutationFn: (name: string) =>
      postJson<Period>(`/api/sheets/${encodeURIComponent(sheet)}/periods/${encodeURIComponent(name)}/close`, { user }),
    onMutate: () => setRefused(null),
    onError: (_e, name) => setRefused(name),
    onSettled: () => queryClient.invalidateQueries({ queryKey: periodsKey(sheet) }),
  });

  const reopen = useMutation({
    mutationFn: (name: string) =>
      postJson<Period>(`/api/sheets/${encodeURIComponent(sheet)}/periods/${encodeURIComponent(name)}/reopen`, { user }),
    onMutate: () => setRefused(null),
    onError: (_e, name) => setRefused(name),
    onSettled: () => queryClient.invalidateQueries({ queryKey: periodsKey(sheet) }),
  });

  // An error goes as soon as its form is changed or submitted again.
  const clearError = () => {
    save.reset();
    setInvalid(null);
  };

  // Refused here, before anything is sent, when the form alone shows it is bad.
  const check = (): string | null => {
    const n = name.trim();
    if (n === '') return 'A period needs a name.';
    if (!DATE.test(from.trim()) || !DATE.test(to.trim())) return 'The dates must be yyyy-mm-dd.';
    if (from.trim() > to.trim()) return 'The from-date must be on or before the to-date.';
    if (periods.some((p) => p.name === n)) return 'There is already a period of that name.';
    const clash = periods.find((p) => p.from <= to.trim() && from.trim() <= p.to);
    if (clash) return `The period overlaps ${clash.name}.`;
    return null;
  };

  const dueIn = (period: Period) => periodDue(period, all, people, rates, floor, late);

  return (
    <section data-testid="periods-panel">
      <h2>Periods</h2>
      <form
        data-testid="period-form"
        onSubmit={(e) => {
          e.preventDefault();
          const problem = check();
          if (problem !== null) {
            save.reset();
            setInvalid(problem);
            return;
          }
          setInvalid(null);
          submitOnce(() => save.mutateAsync({ name: name.trim(), from: from.trim(), to: to.trim() }));
        }}
      >
        <label>
          Name{' '}
          <input
            data-testid="period-form-name"
            value={name}
            onChange={(e) => {
              setName(e.target.value);
              clearError();
            }}
          />
        </label>{' '}
        <label>
          From{' '}
          <input
            data-testid="period-form-from"
            placeholder="yyyy-mm-dd"
            value={from}
            onChange={(e) => {
              setFrom(e.target.value);
              clearError();
            }}
          />
        </label>{' '}
        <label>
          To{' '}
          <input
            data-testid="period-form-to"
            placeholder="yyyy-mm-dd"
            value={to}
            onChange={(e) => {
              setTo(e.target.value);
              clearError();
            }}
          />
        </label>{' '}
        <button type="submit" data-testid="period-form-submit" disabled={save.isPending}>
          Add period
        </button>
        {(invalid !== null || save.isError) && (
          <span data-testid="period-form-error" role="alert">
            {' '}
            {invalid ?? 'Could not add this period.'}
          </span>
        )}
      </form>
      <table data-testid="period-list">
        <thead>
          <tr>
            <th>Period</th>
            <th>From</th>
            <th>To</th>
            <th>Due</th>
            <th>Closed</th>
            <th></th>
          </tr>
        </thead>
        <tbody>
          {periods.map((p) => (
            <tr key={p.name} data-testid={`period-row-${p.name}`}>
              <td data-testid="period-name">{p.name}</td>
              <td data-testid="period-from">{p.from}</td>
              <td data-testid="period-to">{p.to}</td>
              <td data-testid="period-due-total">{dueIn(p)}</td>
              <td data-testid="period-closed">{p.closed ? 'yes' : 'no'}</td>
              <td>
                <button
                  type="button"
                  data-testid="period-close"
                  disabled={close.isPending}
                  onClick={() => close.mutate(p.name)}
                >
                  Close
                </button>{' '}
                <button
                  type="button"
                  data-testid="period-reopen"
                  disabled={reopen.isPending}
                  onClick={() => reopen.mutate(p.name)}
                >
                  Reopen
                </button>
                {refused === p.name && (
                  <span data-testid="period-error" role="alert">
                    {' '}
                    Could not change this period.
                  </span>
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

export const contribution = SheetPanels.fill({ order: 6, Component: PeriodsPanel });
import { PersonCells, PersonColumns } from '../../slots/defs/personRow';
import { useClaims } from '../claims/useClaims';
import { type Person } from '../people/usePeople';
import { showDue, useRates } from '../rates/useRates';
import { useFloor, useLate } from '../settings/useSettings';
import { personPeriodDueCents, usePeriods } from './usePeriods';

/** One header per period on the sheet. */
function PeriodColumns({ sheet }: { user: string; sheet: string }) {
  const { data: periods = [] } = usePeriods(sheet);
  return (
    <>
      {periods.map((p) => (
        <th key={p.name}>{p.name}</th>
      ))}
    </>
  );
}

/**
 * A person's due-total for every period on the sheet: the due of their counted claims dated in it,
 * or, once the period is closed, the figure fixed then (0.00 for a person added since).
 */
function PersonPeriods({ sheet, person }: { user: string; sheet: string; person: Person }) {
  const { data: periods = [] } = usePeriods(sheet);
  const { data: claims = [] } = useClaims(sheet);
  const { data: rates = [] } = useRates(sheet);
  const floor = useFloor(sheet);
  const late = useLate(sheet);
  return (
    <>
      {periods.map((p) => (
        <td key={p.name} data-testid={`person-period-${p.name}-due-total`}>
          {showDue(personPeriodDueCents(p, person, claims, rates, floor, late))}
        </td>
      ))}
    </>
  );
}

export const contributions = [
  PersonColumns.fill({ order: 15, Component: PeriodColumns }),
  PersonCells.fill({ order: 15, Component: PersonPeriods }),
];
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { claimDueCents, live, type Claim, type Late } from '../claims/useClaims';
import { gradeOn, heldOnBy, type Person } from '../people/usePeople';
import { hundredths, rateOn, totalDue, type Rate } from '../rates/useRates';
import type { FloorOn } from '../settings/useSettings';

/** A period as the server sends it: its name, its from and to dates (yyyy-mm-dd), inclusive, whether
 *  it is closed and, when it is, the due-total fixed when it was closed and each person's (by person
 *  id; a person not in it, added since, has 0.00). */
export type Period = {
  name: string;
  from: string;
  to: string;
  closed: boolean;
  closedTotal: string | null;
  closedPersonTotals: Record<string, string>;
};

export const periodsKey = (sheet: string) => ['sheet', sheet, 'periods'] as const;

/** The sheet's periods, by from-date, re-read whenever the sheet is loaded. */
export function usePeriods(sheet: string) {
  return useQuery({
    queryKey: periodsKey(sheet),
    queryFn: () => getJson<Period[]>(`/api/sheets/${encodeURIComponent(sheet)}/periods`),
    staleTime: 0,
    gcTime: 0,
  });
}

/** A date the server accepts: yyyy-mm-dd. */
export const DATE = /^\d{4}-\d{2}-\d{2}$/;

/** The period whose dates contain `date` (yyyy-mm-dd), or undefined when none does. Periods never
 *  overlap, so there is at most one. */
export function periodOf(periods: Period[], date: string): Period | undefined {
  return periods.find((p) => p.from <= date && date <= p.to);
}

/** A person's due-total for a period, in cents: the one fixed when the period was closed (0 for a
 *  person added since), else the figures of their counted (OPEN or SETTLED) claims dated in it, not
 *  OPEN ones dated within their hold unless stated, n/a ones skipped. */
export function personPeriodDueCents(period: Period, person: Person, claims: Claim[], rates: Rate[], floor: FloorOn, late: Late): bigint {
  if (period.closed) {
    const fixed = period.closedPersonTotals?.[String(person.id)];
    return fixed === undefined ? 0n : hundredths(fixed);
  }
  return live(claims, heldOnBy([person]))
    .filter((c) => c.personId === person.id && periodOf([period], c.date) !== undefined)
    .reduce<bigint>((sum, c) => sum + (claimDueCents(c, floor, rateOn(rates, gradeOn(person, c.date), c.date), late) ?? 0n), 0n);
}

/** A period's due-total: everyone's due-total for it added up. */
export function periodDue(period: Period, claims: Claim[], people: Person[], rates: Rate[], floor: FloorOn, late: Late): string {
  return totalDue(people.map((p) => personPeriodDueCents(period, p, claims, rates, floor, late)));
}
